      {=og_include('blocks/rating.latte', ['p' => ['value' => og_get($v_q, ['rating']), 'label' => og_tpl(og_get($v_labels, ['rating']), [og_get($v_q, ['rating'])])]])|noescape}
    {/if}
    {if og_t(og_eq(og_get($v_item, ['mark']), 'icon'))}
      {capture $c_6}
        {=og_include('icons/LucideIcon.latte', ['name' => og_s(og_get($v_q, ['mark'])), 'size' => 24])|noescape}
      {/capture}
      {=og_include('compose/Inline.latte', ['class' => 'text-muted-foreground', 'attrs' => og_attrs(['data-testid', 'mark']), 'children' => (string) $c_6])|noescape}
    {/if}
    {capture $c_7}
